918	// stageOn 在指定状态上应用一笔扣款与记录，返回回滚函数（恢复该项执行前的
919	// 余额与记录长度）。
920	func stageOn(st *ledgerState, key balanceKey, newBal int64, rec Record) func() {
921		oldBal, hadKey := st.Balances[key]
922		oldLen := len(st.Settlements)
923		st.Balances[key] = newBal
924		st.Settlements = append(st.Settlements, rec)
925		return func() {
926			if hadKey {
927				st.Balances[key] = oldBal
928			} else {
929				delete(st.Balances, key)
930			}
931			st.Settlements = st.Settlements[:oldLen]
932		}
933	}
934	
935	// validateRefundRequest 校验一项退款请求：退款编号、原付款编号、原因三者
936	// 都必须非空，校验顺序即对外约定（id → settlement_id → reason）。
937	// 未通过校验的编号不占用退款资格，之后可修改后重新提交。
938	func validateRefundRequest(req *RefundRequest) (string, bool) {
939		if req.ID == "" {
940			return reasonEmptyRefundID, false
941		}
942		if req.SettlementID == "" {
943			return reasonEmptySettlement, false
944		}
945		if req.Reason == "" {
946			return reasonEmptyReason, false
947		}
948		return "", true
949	}
950	
951	// refundEffect 是一笔预计成功退款的全部账本效果：退回哪个组合、退回多少、
952	// 留下什么退款记录。它由退款规则产生，本身尚未生效；是否生效、如何生效
953	// （真实落盘，失败则回滚）由生效策略决定。
954	type refundEffect struct {
955		key    balanceKey
956		amount int64
957		record RefundRecord
958	}
959	
960	// attachRefundDetail 把一笔成功退款（首次成功或幂等重复携带的同一条原记录）
961	// 的统一详情填入逐项结果：原付款编号、账户、资产、退款总额、原因与完整退款
962	// 记录。首次成功与重复申请共用这一个出口，保证两者拼装出的详情逐字一致。
963	func attachRefundDetail(res *RefundResult, rec RefundRecord) {
964		res.Reason = rec.Reason
965		res.SettlementID = rec.SettlementID
966		res.Account = rec.Account
967		res.Asset = rec.Asset
968		res.Charged = rec.Charged
969		cp := rec
970		res.Record = &cp
971	}
972	
973	// judgeRefund 按退款规则评估一项请求，只读取状态 st，不产生任何副作用。
974	// 返回逐项结果；预计成功时结果只填编号，退款效果以 refundEffect 描述，
975	// 由调用方交给生效策略落地。判定顺序即对外约定：参数校验、已成功退款编号
976	// 的重复/冲突（优先于目标判断，即使新目标不存在也不退化成 not_found）、
977	// 目标结算存在性、目标是否已被其他退款编号退回。
978	func judgeRefund(req *RefundRequest, st *ledgerState) (RefundResult, *refundEffect) {
979		res := RefundResult{ID: req.ID}
980	
981		// 1. 参数校验。未通过的编号不占用退款资格。
982		if reason, ok := validateRefundRequest(req); !ok {
983			res.Status = StatusInvalid
984			res.Reason = reason
985			return res, nil
986		}
987	
988		// 2. 已成功退款编号优先判定：目标与原因都相同则幂等返回原退款记录；
989		//    任一不同则冲突（即使新目标不存在也不能退化成 not_found）。
990		//    两者都不再入账。本批次内先成功的同编号项也在此被看到。
991		if prior, exists := findRefundIn(st.Refunds, req.ID); exists {
992			if prior.SettlementID == req.SettlementID && prior.Reason == req.Reason {
993				res.Status = StatusDuplicate
994				attachRefundDetail(&res, prior)
995			} else {
996				res.Status = StatusConflict
997				res.Reason = reasonRefundConflict
998			}
999			return res, nil
1000		}
1001	
1002		// 3. 新退款编号：目标必须是一笔成功结算（原付款只曾失败也算不存在）。
1003		target, exists := findRecordIn(st.Settlements, req.SettlementID)
1004		if !exists {
1005			res.Status = StatusNotFound
1006			res.Reason = fmt.Sprintf(reasonSettlementGone, req.SettlementID)
1007			return res, nil
1008		}
1009	
1010		// 4. 每笔原付款最多退回一次：已被其他退款编号退回则报告已退款，不加余额。
1011		if prior, refunded := findRefundOfSettlementIn(st.Refunds, req.SettlementID); refunded {
1012			res.Status = StatusAlreadyRefunded
1013			res.Reason = fmt.Sprintf(reasonAlreadyRefunded, req.SettlementID, prior.ID)
1014			return res, nil
1015		}
1016	
1017		// 5. 预计成功：全额（amount 与当时手续费一并，即以原结算的 charged 为准）
1018		//    退回原账户、原资产；序号按当前退款历史长度连续递增。
1019		rec := RefundRecord{
1020			ID:           req.ID,
1021			SettlementID: target.ID,
1022			Reason:       req.Reason,
1023			Account:      target.Account,
1024			Asset:        target.Asset,
1025			Amount:       target.Amount,
1026			Fee:          target.Fee,
1027			Charged:      target.Charged,
1028			AfterSeq:     int64(len(st.Settlements)),
1029			Seq:          int64(len(st.Refunds)) + 1,
1030		}
1031		return res, &refundEffect{
1032			key:    balanceKey{target.Account, target.Asset},
1033			amount: target.Charged,
1034			record: rec,
1035		}
1036	}
1037	
1038	// commitRefund 是退款生效策略：把一笔预计成功的退款应用到状态 st 上。
1039	// 返回 nil 表示已生效；返回非 nil 表示保存失败，且 st 必须已恢复到
1040	// 该项执行之前的余额与退款历史。
1041	type commitRefund func(st *ledgerState, eff refundEffect) error
1042	
1043	// runRefundBatch 按输入顺序在给定状态 st 上处理整个退款批次，返回逐项结果。
1044	// 退款规则（judgeRefund）与生效（commit）分离：规则只读取 st 给出判定和
1045	// 预计退款效果，不改动任何状态；生效策略决定效果如何落地——真实提交先改
1046	// 内存再原子落盘、失败回滚并报告 storage_error。保存失败时 commit 已回滚
1047	// 该项（余额与退款历史恢复原样），该项不占退款编号、不把原付款标成已退款，
1048	// 前项成功保留、后项继续处理。调用方必须持有 reg.mu。
1049	func runRefundBatch(batch RefundBatch, st *ledgerState, commit commitRefund) []RefundResult {
1050		out := make([]RefundResult, 0, len(batch.Refunds))
1051		for i := range batch.Refunds {
1052			req := &batch.Refunds[i]
1053	
1054			// 1. 规则判定：纯读取，不产生任何副作用。
1055			res, eff := judgeRefund(req, st)
1056			if eff == nil {
1057				out = append(out, res)
1058				continue
1059			}
1060	
1061			// 2. 生效：保存失败时 commit 已回滚该项（余额与历史恢复原样），
1062			//    该项报告 storage_error，不留退款记录、不占退款序号，后项继续。
1063			if err := commit(st, *eff); err != nil {
1064				res.Status = StatusStorage
1065				res.Reason = err.Error()
1066				out = append(out, res)
1067				continue
1068			}
1069	
1070			// 3. 成功落账：与重复申请一样通过统一出口拼装详情。
1071			res.Status = StatusRefundSuccess
1072			attachRefundDetail(&res, eff.record)
1073			out = append(out, res)
1074		}
1075		return out
1076	}
1077	
1078	// persistRefund 是真实退款的生效策略：先在内存生效，再原子落盘；
1079	// 落盘失败回滚该项（恢复余额与退款历史），并返回存储错误。
1080	func (l *Ledger) persistRefund(st *ledgerState, eff refundEffect) error {
1081		rollback := stageRefundOn(st, eff.key, st.Balances[eff.key]+eff.amount, eff.record)
1082		if err := l.persistLocked(); err != nil {
1083			rollback()
1084			return err
1085		}
1086		return nil
1087	}
1088	
1089	// stageRefundOn 在指定状态上应用一笔退款（余额增加 + 退款记录追加），
1090	// 返回回滚函数（恢复该项执行前的余额与退款记录长度）。
1091	func stageRefundOn(st *ledgerState, key balanceKey, newBal int64, rec RefundRecord) func() {
1092		oldBal, hadKey := st.Balances[key]
1093		oldLen := len(st.Refunds)
1094		st.Balances[key] = newBal
1095		st.Refunds = append(st.Refunds, rec)
1096		return func() {
1097			if hadKey {
1098				st.Balances[key] = oldBal
1099			} else {
1100				delete(st.Balances, key)
1101			}
1102			st.Refunds = st.Refunds[:oldLen]
1103		}
1104	}
1105	
1106	// findRefundIn 在给定退款历史中按编号查找成功记录。
1107	func findRefundIn(refunds []RefundRecord, id string) (RefundRecord, bool) {
1108		// 退款按成功顺序追加且 ID 唯一；单机账本量级直接扫描。
1109		for _, r := range refunds {
1110			if r.ID == id {
1111				return r, true
1112			}
1113		}
1114		return RefundRecord{}, false
1115	}
1116	
1117	// findRefundOfSettlementIn 返回退回指定结算的那笔退款（每笔结算最多一笔）。
1118	func findRefundOfSettlementIn(refunds []RefundRecord, settlementID string) (RefundRecord, bool) {
1119		for _, r := range refunds {
1120			if r.SettlementID == settlementID {
1121				return r, true
1122			}
1123		}
1124		return RefundRecord{}, false
1125	}
1126	
1127	// Refund 按输入顺序处理一个退款批次。各项独立处理：后项能看到前项成功退回的
1128	// 余额；任一项失败不影响其余项（存储错误只回滚出错项本身，前项保留，后项继续）。
1129	// 结果与输入逐项对应，空批次返回空结果。
1130	//
1131	// 语义：
1132	//   - 参数合法时，已成功的退款编号优先判定：目标结算与原因都相同返回 duplicate
1133	//     及原退款记录（不再入账）；任一不同返回 conflict（即使新目标不存在也一样，
1134	//     不能退化成 not_found）。
1135	//   - 新退款编号：找不到成功结算（含原付款只曾失败）返回 not_found；
1136	//     该结算已被其他退款编号退回返回 already_refunded，不增加余额。
1137	//   - 成功时把原记录的 charged（含当时已扣手续费）全额退回原账户、原资产；
1138	//     退款金额与去向完全由原结算确定，原结算记录及其编号、顺序保持不变。
1139	//   - 失败申请（参数错误、目标不存在、已退款、冲突、存储错误）不占用退款编号，
1140	//     之后可修改原因或目标再提交。
1141	func (l *Ledger) Refund(batch RefundBatch) (*RefundBatchResult, error) {
1142		if err := l.beginOp(); err != nil {
1143			return nil, err
1144		}
1145		defer l.endOp()
1146	
1147		l.reg.mu.Lock()
1148		defer l.reg.mu.Unlock()
1149	
1150		results := runRefundBatch(batch, l.reg.state, l.persistRefund)
1151		return &RefundBatchResult{Results: results}, nil
1152	}
1153	
1154	func (l *Ledger) stateView() *ledgerState { return l.reg.state }
1155	
1156	// sameRequest 比较全部付款字段与费率。付款字段：账户、付款方、资产、金额、nonce。
1157	func sameRequest(r Record, it *PaymentIntent, amount int64, feeBps int) bool {
1158		return r.Account == it.Account &&
1159			r.Paymaster == it.Paymaster &&
1160			r.Asset == it.Asset &&
1161			r.Amount == amount &&
1162			r.Nonce == it.Nonce &&
1163			r.FeeBps == feeBps
1164	}
1165	
1166	// Query 返回余额视图（按账户、资产排序，保证确定性）与按成功先后排列的记录。
1167	func (l *Ledger) Query() (*Snapshot, error) {
1168		if err := l.beginOp(); err != nil {
1169			return nil, err
1170		}
1171		defer l.endOp()
1172		l.reg.mu.Lock()
1173		defer l.reg.mu.Unlock()
1174	
1175		st := l.stateView()
1176		bals := make([]BalanceView, 0, len(st.Balances))
1177		for k, v := range st.Balances {
1178			bals = append(bals, BalanceView{Account: k.account, Asset: k.asset, Balance: v})
1179		}
1180		sortBalances(bals)
1181		recs := make([]Record, len(st.Settlements))
1182		copy(recs, st.Settlements)
1183		refunds := make([]RefundRecord, len(st.Refunds))
1184		copy(refunds, st.Refunds)
1185		return &Snapshot{Balances: bals, Settlements: recs, Refunds: refunds}, nil
1186	}
1187	
1188	// Balance 返回单个 (账户, 资产) 组合的余额；组合不存在按 0 处理。
1189	func (l *Ledger) Balance(account, asset string) (int64, error) {
1190		if err := l.beginOp(); err != nil {
1191			return 0, err
1192		}
1193		defer l.endOp()
1194		l.reg.mu.Lock()
1195		defer l.reg.mu.Unlock()
1196		return l.stateView().Balances[balanceKey{account, asset}], nil
1197	}
1198	
1199	func sortBalances(bals []BalanceView) {
1200		sort.Slice(bals, func(i, j int) bool {
1201			if bals[i].Account != bals[j].Account {
1202				return bals[i].Account < bals[j].Account
1203			}
1204			return bals[i].Asset < bals[j].Asset
1205		})
1206	}
1207	
1208	// persistLocked 将当前状态原子写入磁盘；调用方必须持有 reg.mu。
1209	func (l *Ledger) persistLocked() error {
1210		if l.reg.failHook != nil && l.reg.failHook.FailNextPersist() {
1211			return ledgerError(ErrStorage, "injected write failure")
1212		}
1213		return atomicWrite(l.path, l.stateView())
1214	}
1215	
1216	// SetFailHook 为该路径的账本安装存储故障注入，仅用于测试。
1217	func SetFailHook(l *Ledger, fw FailWriter) {
1218		l.reg.failHook = fw
1219	}
1220

